-- Schema-only prerequisites for the older PULSE-Staging project; contains no production records.
-- One-time bootstrap against its existing core tables. Do not run on production.
create table if not exists public.club_training_patterns (id bigint generated by default as identity not null, club_id bigint not null, facility_id bigint, session_name text default 'Club Session'::text not null, day_of_week smallint not null, start_time time without time zone, end_time time without time zone, venue_text text, valid_from date, valid_to date, publicly_verified boolean default false not null, created_at timestamp with time zone default now() not null, semester_label text, constraint club_training_patterns_day_of_week_check CHECK (((day_of_week >= 1) AND (day_of_week <= 7))), constraint club_training_patterns_pkey PRIMARY KEY (id)); alter table public.club_training_patterns enable row level security;
create table if not exists public.demo_recipients (persona_key text not null, persona_label text not null, member_id bigint, recipient_name text, email text, telegram_chat_id bigint, copy_all boolean default false not null, active boolean default true not null, updated_at timestamp with time zone default now() not null, constraint demo_recipients_email_check CHECK (((email IS NULL) OR (email ~ '^[^@\s,]+@[^@\s,]+\.[^@\s,]+$'::text))), constraint demo_recipients_has_target CHECK (((member_id IS NOT NULL) OR copy_all)), constraint demo_recipients_member_id_key UNIQUE (member_id), constraint demo_recipients_pkey PRIMARY KEY (persona_key)); alter table public.demo_recipients enable row level security;
create table if not exists public.exco_availability (id bigint generated by default as identity not null, user_id integer not null, week_key text not null, day_index integer not null, hour_index integer not null, is_available boolean default true, updated_at timestamp with time zone default now(), constraint exco_availability_pkey PRIMARY KEY (id), constraint exco_availability_user_id_week_key_day_index_hour_index_key UNIQUE (user_id, week_key, day_index, hour_index)); alter table public.exco_availability enable row level security;
create table if not exists public.exco_members (email text not null, cca text not null, full_name text, "position" text, telegram_handle text, onboarded_at timestamp with time zone, created_at timestamp with time zone default now(), constraint exco_members_pkey PRIMARY KEY (email, cca)); alter table public.exco_members enable row level security;
create table if not exists public.facility_transfers (id bigint generated by default as identity not null, booking_id bigint not null, releasing_club_id bigint not null, claiming_club_id bigint, audit_voucher_id text, transfer_status text default 'Proposed Peer Transfer'::text not null, released_at timestamp with time zone, claimed_at timestamp with time zone, reviewed_at timestamp with time zone, reviewed_by uuid, rejection_reason text, email_status text default 'NOT_REQUIRED'::text not null, created_at timestamp with time zone default now() not null, released_by_member_id bigint, claimed_by_member_id bigint, reviewed_by_member_id bigint, signoff_reminder_sent_at timestamp with time zone, constraint facility_transfers_audit_voucher_id_key UNIQUE (audit_voucher_id), constraint facility_transfers_pkey PRIMARY KEY (id), constraint pulse_transfer_not_self_check CHECK (((claiming_club_id IS NULL) OR (claiming_club_id <> releasing_club_id))) NOT VALID, constraint pulse_transfer_status_check CHECK ((transfer_status = ANY (ARRAY['Proposed Peer Transfer'::text, 'Pending Admin Sign-off'::text, 'Officially Confirmed Booking'::text, 'Rejected'::text, 'Cancelled'::text, 'Expired'::text]))) NOT VALID); alter table public.facility_transfers enable row level security;
create table if not exists public.notifications (id bigint generated by default as identity not null, recipient_club_id bigint, recipient_user_id uuid, type text not null, title text not null, body text not null, booking_id bigint, transfer_id bigint, action_url text, is_read boolean default false not null, created_at timestamp with time zone default now() not null, recipient_member_id bigint, waitlist_entry_id bigint, telegram_status text default 'NOT_REQUIRED'::text not null, constraint notifications_pkey PRIMARY KEY (id), constraint pulse_telegram_status_check CHECK ((telegram_status = ANY (ARRAY['NOT_REQUIRED'::text, 'PENDING'::text, 'SENT'::text, 'NO_CHAT'::text, 'FAILED'::text]))) NOT VALID); alter table public.notifications enable row level security;
create table if not exists public.transfer_audit_log (id bigint generated by default as identity not null, transfer_id bigint not null, booking_id bigint not null, event_type text not null, actor_user_id uuid, actor_club_id bigint, details jsonb default '{}'::jsonb not null, created_at timestamp with time zone default now() not null, actor_member_id bigint, constraint transfer_audit_log_event_type_check CHECK ((event_type = ANY (ARRAY['RELEASED'::text, 'CLAIMED'::text, 'EMAIL_READY'::text, 'EMAIL_SENT'::text, 'APPROVED'::text, 'REJECTED'::text, 'CANCELLED'::text, 'OSL_EMAIL_REQUESTED'::text, 'RELEASE_UNDONE'::text, 'RELISTED_AFTER_REJECTION'::text, 'SIGNOFF_EXPIRED'::text]))), constraint transfer_audit_log_pkey PRIMARY KEY (id)); alter table public.transfer_audit_log enable row level security;
create table if not exists public.transfer_email_config (id boolean default true not null, to_emails text[] default '{}'::text[] not null, cc_emails text[] default '{}'::text[] not null, constraint transfer_email_config_id_check CHECK ((id = true)), constraint transfer_email_config_pkey PRIMARY KEY (id)); alter table public.transfer_email_config enable row level security;
create table if not exists public.transfer_emails (id bigint generated by default as identity not null, transfer_id bigint not null, booking_id bigint not null, sender_user_id uuid, sender_club_id bigint not null, from_email text not null, to_emails text[] not null, cc_emails text[] not null, subject text not null, body text not null, provider_message_id text, status text default 'DRAFT'::text not null, sent_at timestamp with time zone, created_at timestamp with time zone default now() not null, email_type text, action_url text, requested_by_member_id bigint, reply_to text, queued_at timestamp with time zone, attempts integer default 0 not null, last_error text, constraint pulse_email_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'QUEUED'::text, 'SENDING'::text, 'SENT'::text, 'FAILED'::text]))) NOT VALID, constraint transfer_emails_pkey PRIMARY KEY (id)); alter table public.transfer_emails enable row level security;
create table if not exists public.waitlist_entries (id bigint generated by default as identity not null, booking_id bigint not null, club_id bigint not null, created_at timestamp with time zone default now() not null, status text default 'WAITING'::text not null, offered_at timestamp with time zone, offer_expires_at timestamp with time zone, claimed_at timestamp with time zone, left_at timestamp with time zone, joined_by_member_id bigint, reminder_sent_at timestamp with time zone, constraint pulse_waitlist_status_check CHECK ((status = ANY (ARRAY['WAITING'::text, 'OFFERED'::text, 'EXPIRED'::text, 'DECLINED'::text, 'LEFT'::text, 'CLAIMED'::text]))) NOT VALID, constraint waitlist_entries_pkey PRIMARY KEY (id)); alter table public.waitlist_entries enable row level security;
