alter table public.transfer_audit_log add constraint transfer_audit_log_actor_user_id_fkey FOREIGN KEY (actor_user_id) REFERENCES auth.users(id);
alter table public.transfer_audit_log add constraint transfer_audit_log_booking_id_fkey FOREIGN KEY (booking_id) REFERENCES facility_bookings(id) ON DELETE CASCADE;
alter table public.transfer_audit_log add constraint transfer_audit_log_transfer_id_fkey FOREIGN KEY (transfer_id) REFERENCES facility_transfers(id) ON DELETE CASCADE;
