-- Restore identity defaults absent from the original minimal staging schema.
do $$ declare t text; v bigint; begin foreach t in array array['clubs','exco_roles'] loop
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name=t and column_name='id' and is_identity='NO' and column_default is null) then
  execute format('alter table public.%I alter column id add generated by default as identity',t);
  execute format('select coalesce(max(id),0) from public.%I',t) into v;
  perform setval(pg_get_serial_sequence('public.'||t,'id'),greatest(v,1),v>0);
 end if; end loop; end $$;
